import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private final RateLimitingService rateLimitingService;

    public SecurityConfig(RateLimitingService rateLimitingService) {
        this.rateLimitingService = rateLimitingService;
    }

    /**
     * In-memory user details service configured without any database.
     */
    @Bean
    public UserDetailsService userDetailsService() {
        UserDetails inMemoryUser = org.springframework.security.core.userdetails.User.builder()
                .username("alex_dev")
                .password("{noop}SecretPass@2026")
                .roles("DEVELOPER")
                .build();

        return new InMemoryUserDetailsManager(inMemoryUser);
    }

    /**
     * Stateless security filter chain with token-bucket rate limiting enforcement.
     */
    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        RateLimitingFilter rateLimitingFilter = new RateLimitingFilter(rateLimitingService);

        http
                .csrf(AbstractHttpConfigurer::disable)
                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .addFilterBefore(rateLimitingFilter, UsernamePasswordAuthenticationFilter.class)
                .authorizeHttpRequests(auth -> auth.anyRequest().permitAll())
                .headers(headers -> headers
                        .httpStrictTransportSecurity(hsts -> hsts
                                .includeSubDomains(true)
                                .maxAgeInSeconds(31536000)
                                .preload(true)
                        )
                );
        return http.build();
    }
}

