import com.example.jwtservicedemo.model.User;
import jakarta.annotation.PostConstruct;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.core.userdetails.UsernameNotFoundException;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Service managing in-memory POJO User instances and serving as Spring Security's UserDetailsService.
 * Hashes passwords using BCrypt to protect against credential leaks and timing attacks.
 */
@Service
public class UserService implements UserDetailsService {

    // Thread-safe in-memory store for POJO users
    private final Map<String, User> userStore = new ConcurrentHashMap<>();
    private final PasswordEncoder passwordEncoder;

    public UserService(PasswordEncoder passwordEncoder) {
        this.passwordEncoder = passwordEncoder;
    }

    public UserService() {
        this(new BCryptPasswordEncoder());
    }

    @PostConstruct
    public void initDefaultUsers() {
        // Seed default in-memory POJO users (passwords will be BCrypt hashed via register)
        register(User.builder()
                .username("alex_dev")
                .password("SecretPass@2026")
                .role("DEVELOPER")
                .build());

        register(User.builder()
                .username("sarah_admin")
                .password("AdminPass#999")
                .role("ADMIN")
                .build());

        register(User.builder()
                .username("john_doe")
                .password("Password@123")
                .role("USER")
                .build());
    }

    /**
     * Authenticates a user against in-memory POJO credentials using BCrypt.
     */
    public Optional<User> authenticate(String username, String rawPassword) {
        if (username == null || rawPassword == null) {
            return Optional.empty();
        }
        User user = userStore.get(username);
        if (user != null && passwordEncoder.matches(rawPassword, user.getPassword())) {
            return Optional.of(user);
        }
        return Optional.empty();
    }

    /**
     * Registers a new POJO user in memory with BCrypt hashed password.
     */
    public User register(User user) {
        if (user.getRole() == null || user.getRole().isBlank()) {
            user.setRole("USER");
        }
        String rawPassword = user.getPassword();
        if (rawPassword != null && !rawPassword.startsWith("$2a$") && !rawPassword.startsWith("$2b$")) {
            user.setPassword(passwordEncoder.encode(rawPassword));
        }
        userStore.put(user.getUsername(), user);
        return user;
    }

